<?php
declare(strict_types=1);

function bookingBridgeOutlet(PDO $pdo,mixed $value):int{
 $id=bookingId($value,'Outlet');$q=$pdo->prepare('SELECT id FROM outlets WHERE id=? AND active=1');$q->execute([$id]);if(!$q->fetchColumn())throw new BookingError('The mapped outlet is missing or inactive.',409);return $id;
}
function bookingBridgePackage(array $package):array{
 $id=bookingId($package['id']??null,'Website package');$name=bookingText($package['name']??null,'Package name',150,true);$category=bookingText($package['service']??null,'Category',24,true);if(!in_array($category,['tint','coating','ppf','wrapping'],true))throw new BookingError('Invalid website package category.');$description=bookingText($package['description']??'','Description',500);$price=bookingMoney($package['price']??null);$duration=filter_var($package['duration']??90,FILTER_VALIDATE_INT);if($duration===false||$duration<30||$duration>720||$duration%30)throw new BookingError('Invalid initial package duration.');return compact('id','name','category','description','price','duration');
}
function bookingBridgeService(PDO $pdo,string $site,int $outlet,array $package):array{
 $p=bookingBridgePackage($package);$q=$pdo->prepare('SELECT service_id FROM sp_booking_website_services WHERE site_hash=? AND outlet_id=? AND package_id=?');$q->execute([$site,$outlet,$p['id']]);$id=(int)$q->fetchColumn();$now=bookingNow()->format('Y-m-d H:i:s');
 if($id){$service=bookingService($pdo,$outlet,$id);if($service['name']!==$p['name']||$service['category']!==$p['category']||$service['description']!==$p['description']||$service['price']!==$p['price'])$pdo->prepare('UPDATE sp_booking_services SET name=?,category=?,description=?,price=?,version=version+1,updated_at=? WHERE id=? AND outlet_id=?')->execute([$p['name'],$p['category'],$p['description'],$p['price'],$now,$id,$outlet]);}
 else{$pdo->prepare('INSERT INTO sp_booking_services(outlet_id,name,category,description,duration_minutes,price,active,created_at,updated_at) VALUES(?,?,?,?,?,?,1,?,?)')->execute([$outlet,$p['name'],$p['category'],$p['description'],$p['duration'],$p['price'],$now,$now]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO sp_booking_website_services(site_hash,outlet_id,package_id,service_id) VALUES(?,?,?,?)')->execute([$site,$outlet,$p['id'],$id]);}
 // SP-Manager retains control of duration and active status after initial import.
 return bookingService($pdo,$outlet,$id);
}
function bookingBridgeMappedService(PDO $pdo,string $site,int $outlet,mixed $package):int{
 $q=$pdo->prepare('SELECT service_id FROM sp_booking_website_services WHERE site_hash=? AND outlet_id=? AND package_id=?');$q->execute([$site,$outlet,bookingId($package,'Package')]);$id=(int)$q->fetchColumn();if(!$id)throw new BookingError('Website packages have not been synchronized for this outlet.',409);return $id;
}
function bookingBridgeImport(PDO $pdo,int $outlet,array $service,array $b):array{
 $reference=bookingText($b['reference']??null,'Existing website reference',32,true);if(!preg_match('/^SP-[A-Za-z0-9-]{8,28}$/D',$reference))throw new BookingError('Invalid existing website reference.');
 $startRaw=bookingText($b['starts_at']??null,'Start time',19,true);$endRaw=bookingText($b['ends_at']??null,'End time',19,true);$zone=new DateTimeZone('Asia/Kuala_Lumpur');$start=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$startRaw,$zone);$end=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$endRaw,$zone);
 if(!$start||!$end||$start->format('Y-m-d H:i:s')!==$startRaw||$end->format('Y-m-d H:i:s')!==$endRaw||$end<=bookingNow()||$start<bookingNow()->modify('-2 days')||$start>bookingNow()->modify('+365 days')||$end<=$start||$end>$start->modify('+12 hours'))throw new BookingError('Only active, valid upcoming website appointments can be imported.');
 $status=bookingText($b['status']??null,'Status',24,true);if(!bookingConsumesCapacity($status))throw new BookingError('Only pending, confirmed or in-progress appointments can be imported.');
 $capacity=(int)bookingSettings($pdo,$outlet)['values']['capacity'];if(bookingPeak(bookingOverlaps($pdo,$outlet,$start,$end),$start,$end)>$capacity)throw new BookingError('An existing website appointment conflicts with SP-Manager capacity. Resolve the slot before activation.',409);
 $name=bookingText($b['customer_name']??null,'Customer name',150,true);$phone=preg_replace('/[\s()+-]/','',bookingText($b['phone']??null,'Phone',32,true));if(!preg_match('/^[0-9]{9,15}$/D',$phone))throw new BookingError('Invalid customer phone.');$email=bookingText($b['email']??'','Email',190);if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new BookingError('Invalid customer email.');$model=bookingText($b['car_model']??null,'Car model',150,true);$plate=bookingText($b['plate']??null,'Plate',32,true);$notes=bookingText($b['notes']??'','Notes',2000);$price=bookingMoney($b['price']??null);$title=bookingText($b['package_name']??$service['name'],'Package name',150,true);$description=bookingText($b['description']??$service['description'],'Description',500);$now=bookingNow()->format('Y-m-d H:i:s');
 $pdo->prepare("INSERT INTO sp_bookings(outlet_id,reference,service_id,service_name,service_category,description,price,starts_at,ends_at,status,customer_name,phone,email,car_model,plate,notes,source,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?, 'website',?,?)")->execute([$outlet,$reference,$service['id'],$title,$service['category'],$description,$price,$startRaw,$endRaw,$status,$name,$phone,$email,$model,$plate,$notes,$now,$now]);$id=(int)$pdo->lastInsertId();bookingEvent($pdo,$outlet,$id,'website_import','Imported existing website appointment '.$reference);$row=bookingRead($pdo,$outlet,$id);spAudit($pdo,'booking.website_import','booking',$id,null,$row);return $row;
}
